CREATE TABLE IF NOT EXISTS price_margin_policy (policy_id uuid PRIMARY KEY, organization_id uuid NOT NULL, entity_id uuid NOT NULL, sku_id uuid, target_price numeric(14,4) NOT NULL, floor_price numeric(14,4) NOT NULL, min_margin_pct numeric(7,3), incentive_basis varchar(30) NOT NULL DEFAULT 'NET_OF_GST', effective_from timestamptz NOT NULL, effective_to timestamptz, active boolean NOT NULL DEFAULT true, notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_price_margin_policy_lookup ON price_margin_policy(organization_id,entity_id,sku_id,active,effective_from);
CREATE TABLE IF NOT EXISTS price_exception (exception_id uuid PRIMARY KEY, organization_id uuid NOT NULL, entity_id uuid NOT NULL, location_id uuid NOT NULL, sku_id uuid NOT NULL, unit_cost numeric(14,4) NOT NULL, proposed_price numeric(14,4) NOT NULL, discount_pct numeric(7,3) NOT NULL DEFAULT 0, taxable_unit_price numeric(14,4) NOT NULL, gst_rate numeric(7,3) NOT NULL DEFAULT 0, margin_pct numeric(7,3) NOT NULL, target_price numeric(14,4), floor_price numeric(14,4), status varchar(30) NOT NULL, reason text, requested_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
